Ext.define('ViewDashlet.view.ViewDashletViewController', {
    extend: 'Ext.app.ViewController',
    alias: 'controller.viewdashlet',

    config: {
        lastChartSelected: null,
        lastGridSelected: null
    },

    OpenWindowWithPost: function(url, windowoption, tabOpen, params) {

        var doc = document,
            f = doc.createElement("form"),
            tmp;

        f.setAttribute("style", "display:none;");
        f.setAttribute("method", "POST");
        f.setAttribute("target", "_blank");
        f.setAttribute("action", url);


        doc.body.appendChild(f);

        for (var i in params) {
            if (params.hasOwnProperty(i)) {
                tmp = doc.createElement("input");
                tmp.setAttribute("type", "hidden");
                tmp.setAttribute("name", i);
                tmp.setAttribute("value", params[i]);

                f.appendChild(tmp);
            }
        }

        f.submit();

        try {
            f.remove();
            doc.removeChild(f);
        } catch (e) {

        }
    },

    selectorSelectionChange: function(model, selected, eOpts) {

        if (selected === null) return;


        var me =this,

            View = me.getView(),

            DashletSpec = View.DashletSpec,
            RestServices = View.RestServices,

            card = me.lookupReference('card'),

            data = selected.data,
            cmd = data.cmd,
            internalID = data.internalID,
            type = data.type,
            tmp;

        switch(cmd){

            case "hide":

                me.lookupReference('altMenu').setHidden(true);

                model.setSelection(null);

                break;

            case "chart":

                if (DashletSpec.laf.viewSpec.type !== "CHART"){

                    DashletSpec.laf.viewSpec.type = "CHART";
                    DashletSpec.laf.viewSpec.chartSpec.type= me.lastChartSelected || DashletSpec.laf.viewSpec.chartSpec.type;

                    View.setSpec( DashletSpec, {
                        update: false,
                        excludeURN: true
                    });

                    View.build();
                }else{
                    return ;
                }

                break;


            case "grid":

                if (DashletSpec.laf.viewSpec.type !== "GRID"){

                    DashletSpec.laf.viewSpec.type = "GRID";

                    DashletSpec.laf.viewSpec.gridSpec = DashletSpec.laf.viewSpec.gridSpec || View.getGridDefaultSpec();
                    DashletSpec.laf.viewSpec.gridSpec.gridGeneral.gridType = me.lastGridSelected || DashletSpec.laf.viewSpec.gridSpec.gridGeneral.gridType;

                    View.setSpec( DashletSpec, {
                        update: false,
                        excludeURN: true
                    });

                    View.build();
                }else{
                    return;
                }

                break;

            case "chart-item":

                tmp = DashletSpec.laf.viewSpec.chartSpec.type;

                if (DashletSpec.laf.viewSpec.type === "CHART" && tmp.category === type.category && tmp.mode === type.mode ){
                    return;
                }

                if (card.getComponent(internalID)){
                    card.setActiveItem(internalID);
                }

                DashletSpec.laf.viewSpec.type = "CHART";
                DashletSpec.laf.viewSpec.chartSpec.type = type;

                View.setSpec( DashletSpec, {
                    update: false,
                    excludeURN: true
                });


                View.build();


                me.lastChartSelected= type;

                break;

            case "grid-item":


                if (DashletSpec.laf.viewSpec.type === "GRID" && DashletSpec.laf.viewSpec.gridSpec.gridGeneral.gridType === type){
                    return;
                }

                if (card.getComponent(internalID)){
                    card.setActiveItem(internalID);
                }

                DashletSpec.laf.viewSpec.type = "GRID";
                DashletSpec.laf.viewSpec.gridSpec.gridGeneral.gridType = type;

                View.setSpec( DashletSpec, {
                    update: false,
                    excludeURN: true
                });

                View.build();


                me.lastGridSelected = type;

                break;

            case "navigate":

                me.navigateTool();

                model.setSelection(null);

                break;

            case "excel":

                me.exportTool();

                model.setSelection(null);

                break;

            case "exportImg":
                me.downloadImg();

                break;

            case "qd":

                tmp = me.lookupReference("querydescriptor");
                item = model.getItem(selected);


                if (tmp.isHidden()){

                    tmp.setHidden(false);

                }else{

                    tmp.setHidden(true);
                }

                model.setSelection(null);

                break;

            case "drill-history-forward":

                if (RestServices.updateHistory(true)){
                    View.build();
                }

                model.setSelection(null);

                break;
            case "drill-history-back":

                if (RestServices.updateHistory(false)){
                    View.build();
                }

                model.setSelection(null);
                break;
        }


    },

    navigateTool: function() {

        var me = this,
            View = me.getView(),
            RestServices = View.RestServices,
            binding = RestServices.BindingCache,
            SessionData = View.SessionData,
            viewQueryEnc = (binding.query).match(/<ViewQuery.*ViewQuery>/gm)[0],
            data,
            domElem,
            id,
            isAdhoc = /\:ad\-hoc\:/.test(binding.queryTemplate.urn || "");

        data = {
            'userLogin': RestServices.User,
            'userTicket': binding.Ticket,
            'viewDesktop': true,
            'idO3ClientSSO': RestServices.idO3ClientSSO
        };

        if (isAdhoc) {

            Ext.Ajax.request({
                method: 'POST',
                async: true,
                url: SessionData.serviceURL_save,
                headers: {
                    'Authorization': "Basic " + (btoa(RestServices.User + ":" + RestServices.Ticket)),
                    'idO3ClientSSO': RestServices.idO3ClientSSO,
                    'x-standard-rest': true
                },
                params: {
                    "username": RestServices.User,
                    "password": RestServices.Ticket,
                    "typeAccept": "text/plain",
                    "x-rest-locale": SessionData.idsLang,
                    "queryCommand": viewQueryEnc,
                    "saveType": 'xml'
                },
                timeout: RestServices.deafult_timeout,
                success: function(response) {

                    var navKey = response.responseText,

                        link = document.createElement('a');

                    link.href = SessionData.urlPrefixPortalAdhoc + "?navKey=" + encodeURIComponent(navKey);
                    link.target="_blank";
                    link.click();
                }
            });

        } else {

            data.viewQuery = Base64.encode(viewQueryEnc);

            me.OpenWindowWithPost(RestServices.urlPrefixPortal, "", "navigate", data);
        }

    },

    exportTool: function() {

        var me = this,
            View = me.getView(),
            RestServices = View.RestServices,
            regex = new RegExp("\"", "g"),
            data = {
                'senchapost': true,
                'username': RestServices.User,
                'password': RestServices.Ticket,
                'export': true,
                'idO3ClientSSO': RestServices.idO3ClientSSO,
                'queryCommand': RestServices.BindingCache.query.replace(regex, "'"),
                'typeAccept': 'application/octet-stream'
            };
        View.addCls('Loader');

        me.fileDownloader(RestServices.exportURL, data, {}, "POST");
    },

    fileDownloader: function(url, params, headers, method) {


        var me = this,
            xhr = new XMLHttpRequest();

        xhr.open(method || "POST", url + (method === "GET" ? ("&" + $.param(params)) : ""), true);
        xhr.responseType = 'arraybuffer';
        xhr.onload = function() {
            if (this.status === 200) {
                var filename = "",
                    disposition = xhr.getResponseHeader('Content-Disposition'),
                    type,
                    blob;

                if (disposition && disposition.indexOf('attachment') !== -1) {
                    var filenameRegex = /filename[^;=\n]*=((['"]).*?\2|[^;\n]*)/,
                        matches = filenameRegex.exec(disposition);
                    if (matches != null && matches[1]) filename = matches[1].replace(/['"]/g, '');
                }

                type = xhr.getResponseHeader('Content-Type');
                blob = new Blob([this.response], {
                    type: type
                });

                if (typeof window.navigator.msSaveBlob !== 'undefined') {
                    // IE workaround for "HTML7007: One or more blob URLs were revoked by closing the blob for which they were created. These URLs will no longer resolve as the data backing the URL has been freed."
                    window.navigator.msSaveBlob(blob, filename);
                } else {
                    var URL = window.URL || window.webkitURL,
                        downloadUrl = URL.createObjectURL(blob);

                    if (filename) {
                        // use HTML5 a[download] attribute to specify filename
                        var a = document.createElement("a");
                        // safari doesn't support this yet
                        if (typeof a.download === 'undefined') {
                            window.location = downloadUrl;
                        } else {
                            a.href = downloadUrl;
                            a.download = filename;
                            document.body.appendChild(a);
                            a.click();
                        }
                    } else {
                        window.location = downloadUrl;
                    }

                    setTimeout(function() {
                        URL.revokeObjectURL(downloadUrl);
                    }, 100); // cleanup
                }
            }else{
                var Translator = DashletHTML.controller.Translator,
                    msg ;

                if (this.status === 506){
                    msg = Translator.getMessage('status_506');
                }else{
                    msg = Translator.getMessage('unknown');
                }

                window.alert(msg);
            }

            me.getView().removeCls('Loader');
        };
        for (var k in headers) {
            xhr.setRequestHeader(k, headers[k]);
        }

        xhr.setRequestHeader('Content-type', 'application/x-www-form-urlencoded;charset=utf-8');
        xhr.send(method === "POST" ? $.param(params) : null);
    },

    doFormPost: function(path, params, method) {
        method = method || "post";

        var form = document.createElement("form");

        form.style.visibility='hidden';
        form.setAttribute("method", method);
        form.setAttribute("action", path);

        for(var key in params) {
            if(params.hasOwnProperty(key)) {
                var hiddenField = document.createElement("input");
                hiddenField.setAttribute("type", "hidden");
                hiddenField.setAttribute("name", key);
                hiddenField.setAttribute("value", params[key]);

                form.appendChild(hiddenField);
            }
        }

        document.body.appendChild(form);
        form.submit();
    },

    downloadImg: function() {

        var me = this,
            View = me.getView(),
            SessionData = View.SessionData,
            DashletSpec = JSON.stringify(View.DashletSpec),
            RestServices = View.RestServices,
            BindingCache = RestServices.BindingCache,
            CardItem = View.lookupReference('card').getLayout().getActiveItem(),

            specTempKey,
            viewQueryTempKey,

            contextSettings = View.DashletSpec.contextSettings,
            tmp, boxSize,

            headers = {
                'Authorization': "Basic " + (btoa(RestServices.User + ":" + RestServices.Ticket)),
                'idO3ClientSSO': RestServices.idO3ClientSSO,
                'x-standard-rest': true,
                "Content-Type": "application/x-www-form-urlencoded;charset=utf-8",
                "username": RestServices.User,
                "password": RestServices.Ticket
            },

            params = {
                "user": RestServices.User,
                "ticket": RestServices.Ticket,
                'idO3ClientSSO': RestServices.idO3ClientSSO,
                "typeAccept": "text/plain",
                "x-rest-locale": SessionData.idsLang,
                "saveType": "json",
                "queryCommand": DashletSpec
            };

        if (/(error|Error)/g.test(CardItem.cls)){
            return;
        }

        View.addCls("Loader");

        // guardo spec
        Ext.Ajax.request({
            method: 'POST',
            async: false,
            url: SessionData.serviceURL_save,
            headers: headers,
            params: params,
            timeout: RestServices.deafult_timeout,
            success: function(response) {
                specTempKey = response.responseText;
            }
        });


        // guardo query
        params.saveType = "xml";
        params.queryCommand = BindingCache.query;

        Ext.Ajax.request({
            method: 'POST',
            async: false,
            url: SessionData.serviceURL_save,
            headers: headers,
            params: params,
            timeout: RestServices.deafult_timeout,
            success: function(response) {
                viewQueryTempKey = response.responseText;
            }
        });

        if (specTempKey && viewQueryTempKey) {

            tmp = contextSettings.exportImage;

            boxSize = tmp.enableCustomSize === "true" ? me.getPhantomSize(tmp.imgWidth, tmp.imgHeight): me.getPhantomSize(undefined, undefined);

            params.width = boxSize.width;
            params.height = boxSize.height;

            params.specTempKey = specTempKey;
            params.viewQueryTempKey = viewQueryTempKey;

            params.typeAccept = "application/octet-stream";

            delete params.queryCommand;
            me.fileDownloader(SessionData.serviceURL_downloadImage, params, headers, "GET");
        }

    },

    getPhantomSize: function(width, height) {
        var me = this,
            view = me.getView(),
            cardContainer = view.lookupReference('card'),
            activeItem = cardContainer.getLayout().getActiveItem(),
            spec  = view.DashletSpec,

            type = spec.laf.viewSpec.type,
            category,

            tmp,

            result = {
                width: width,
                height: height
            };



        if (type === "CHART"){

			result.width = result.width || view.getWidth() || 800;
			result.height = result.height || view.getHeight() || 600;
        }else{



            if (result.height === undefined){
                category = spec.laf.viewSpec.gridSpec.gridGeneral.gridType;

                switch(category){
                    case "advanced":

                        var gridView = activeItem.getView(),
                            gridRowSize = gridView.getStore().count(),
                            gridRow = gridRowSize === 0 ? undefined : gridView.getRow(0),
                            offsetHeight =  gridRow ? gridRow.clientHeight : 20 ;

                        gridRowSize = gridRowSize === 0 ? 1: gridRowSize;
                        result.height = gridRowSize * offsetHeight + 50;


                        break;

                    case "list":

                        var dom = activeItem.el.dom,
                            table = dom.querySelector('table'),
                            offsetHeight = table.clientHeight;

                        result.height = offsetHeight + 20;

                        break;
                    case "olap":

                        var dom = activeItem.el.dom,
                            table = dom.firstChild,
                            offsetHeight = table.clientHeight;

                        result.height = offsetHeight + 20;


                        break;
                }
            }


            if (result.width === undefined){
                category = spec.laf.viewSpec.gridSpec.gridGeneral.gridType;

                switch(category){
                    case "advanced":

                        var viewGrid  = activeItem.getView(),
                            rect = viewGrid.el.dom.querySelector('.x-grid-item-container').getBoundingClientRect();

                        result.width = rect.width + 20;
                        break;
                    case "olap":

                        var rect = activeItem.el.dom.querySelector('table').getBoundingClientRect();
                        result.width = rect.width + 40;

                        break;
                    case "list":

                        var list = cardContainer.getLayout().getActiveItem(),
                            dom = list.el.dom,
                            offsetWidth = dom.clientWidth + 10;

                        result.width = offsetWidth;

                        break;
                }
            }
        }

        result.width  = Math.ceil(result.width);
        result.height  = Math.ceil(result.height);

        return result;
    }

});
